/* Moby update: advance a timer from a collision query, switch state, aim head angles. */
void handle_blarg_helicopter_hits(char *m) {
    int st;
    float fv;
    int res;
    struct BlargHelicopterVars *d;
    struct HitMessage *r;
    float a, b, p, q;
    d = (struct BlargHelicopterVars *)((Moby *)m)->pvars;
    fv = 0.0f;
    r = (struct HitMessage *)MobyGetHitMessage(m, 0x330000, 0);
    res = ComputeHitResponse(m, r, &d->health, 0, &st, &fv, 0, 4);
    if (st != 1 && ((Moby *)m)->state != 5) {
        float t = d->health - fv;
        d->health = t;
        if (res == 1 || t <= 0.0f) {
            ((Moby *)m)->state = 5;
        } else if (res != 0xB) {
            d->flash = 0xB4;
            RerollEffectCounter(m, &d->color_fade);
            if (r->unk_10.f[3] == 5627.925f && ((Moby *)m)->state != 4) {
                a = fast_atan2(((Moby *)m)->pos.x - r->unk_00, ((Moby *)m)->pos.y - r->unk_04);
                b = FastSubRots(a, ((Moby *)m)->rot.z);
                p = FastCos(b) * 0.08726646f;
                q = FastSin(b) * -0.34906584f;
                if (absolute_float(((Moby *)m)->rot.x) < absolute_float(q)) {
                    ((Moby *)m)->rot.x = q;
                    d->sway_y = 0.0f;
                }
                if (absolute_float(((Moby *)m)->rot.y) < absolute_float(p)) {
                    ((Moby *)m)->rot.y = p;
                    d->sway_z = 0.0f;
                }
                d->sway_rate = g_frame_time * 4.0f;
                d->sway_timer = scale_ticks(0x3C);
                ((Moby *)m)->command = ((Moby *)m)->state;
                ((Moby *)m)->state = 4;
                Moby_PlaySound(1, 0, (int)m);
            }
        }
    }
    ((Moby *)m)->hit_slot = 0xFF;
    StepColorFade(m, &d->color_fade);
}

/* Statue update: wait for a hit, then play a sound, drop bolts, break into three pieces and delete. */
void statue_update(Moby *m) {
    int flag = 0;
    float z;
    char *p, *pos, *vel;
    struct HitMessage *x = (struct HitMessage *)MobyGetHitMessage(m, 0x10000, 0);
    switch (m->state) {
        case 0:
            m->state = 1;
            break;
        case 1:
            if (x != 0) {
                if (x->damage > 0.0f)
                    flag = 1;
            }
            if (flag)
                m->state = 2;
            break;
        case 2:
            Moby_PlaySound(0, 0, (int)m);
            z = 0.0f;
            p = kerwan_zero_vec;
            pos = (unsigned char *)&m->pos;
            spawn_proximity_gated_bolts(m);
            vel = (unsigned char *)&m->rot;
            SpawnBreakFragment(m, 0x727, pos, vel, 0, 0, z, p, p, p);
            SpawnBreakFragment(m, 0x728, pos, vel, 0, 0, z, p, p, p);
            SpawnBreakFragment(m, 0x729, pos, vel, 0, 0, z, p, p, p);
            DeleteMoby(m);
            break;
    }
}
